    const cards=rows.map(row=>`<article class="categorized-context-card" data-research-object="${esc(row.context_id)}"><header><div><span>${esc(row.code)}</span><h3 data-toc="false">${esc(raw(row.title?.[language]||row.title?.en||row.context_id))}</h3><small>${pick("EvidenceContext · 不作为独立 ResearchItem", "EvidenceContext · not a standalone ResearchItem")}</small></div>${badge(row.status)}</header><p>${esc(raw(row.decision))}</p><div class="categorized-context-boundary"><b>${pick("重开 / 权限边界", "Reopen / authority boundary")}</b><span>${esc(raw(row.reopen_condition||pick("无自动科研权限","no automatic scientific authority")))}</span></div></article>`).join("");
