    if(/identifiability|operationalization|protocol/.test(raw))return {tone:"identify",label:pick("实验区分不了机制","The test cannot distinguish the mechanism"),plain:pick("当前观测或实验设计不能判断结果是否来自候选声称的新机制，因此继续扩大实验也不会得到清楚结论。","The current observations cannot attribute the result to the claimed mechanism, so scaling the same test would not clarify the claim.")};
